let category='전체';
const search=document.querySelector('#search'), list=document.querySelector('#machines'), dialog=document.querySelector('#detail');
const normalize=value=>value.toLowerCase().replace(/\s/g,'');
const filters=document.querySelector('.filters');
['전체','가슴','등','어깨','복부','팔','하체'].forEach(name=>{const button=document.createElement('button');button.textContent=name;button.setAttribute('aria-pressed',name==='전체');button.onclick=()=>{category=name;filters.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b===button));render();};filters.append(button);});
function render(){const query=normalize(search.value);const found=machines.filter(m=>(category==='전체'||(m.categories||[m.category]).includes(category))&&normalize([m.name,m.en,m.aliases,m.category,...(m.modes||[]).flatMap(mode=>[mode.name,mode.en])].join(' ')).includes(query));document.querySelector('#count').textContent=`${category} · 머신 ${found.length}개`;list.replaceChildren();found.forEach(m=>{const button=document.createElement('button');button.className='machine';button.innerHTML=`<span class="machine-number">${m.id}</span><span class="machine-text"><strong>${m.name}</strong><small>${m.category} &nbsp; / &nbsp; ${m.en}</small></span><span class="machine-arrow" aria-hidden="true">↗</span>`;button.setAttribute('aria-label',`${m.name} 안내 보기`);button.onclick=()=>{const matched=m.modes?.findIndex(v=>query!==''&&normalize(v.name+v.en).includes(query));const byCategory=m.modes?.findIndex(v=>category!=='전체'&&v.category.split(' · ').includes(category));showMachine(m,matched>=0?matched:byCategory>=0?byCategory:0);};list.append(button);});document.querySelector('#empty').hidden=found.length!==0;}
let disposeMotion=()=>{};
function open(content){disposeMotion();disposeMotion=()=>{};document.querySelector('#detail-content').innerHTML=content;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';}
function exerciseContent(m){return `${renderVisualGuide(m)}<section class="detail-section"><h3><span>01</span>기본 설정</h3><ul class="setup-list">${m.setup.map(t=>`<li>${t}</li>`).join('')}</ul></section><section class="detail-section"><h3><span>02</span>사용법 3단계</h3><ol class="exercise-steps">${m.steps.map(t=>`<li>${t}</li>`).join('')}</ol></section><section class="detail-section trainer-tip"><h3><span>03</span>트레이너의 팁!</h3>${m.tip.split(/\n+|(?<=[.!?])\s+/).map(t=>t.trim()).filter(Boolean).map(t=>`<p>${t}</p>`).join('')}</section><p class="machine-note">${m.note}</p><details class="sources"><summary>사용법 참고 자료</summary>${m.source?`<a href="${m.source}" target="_blank" rel="noopener noreferrer">${m.sourceLabel} ↗</a><p>기본 설정과 사용법은 참고 자료를 요약했습니다. 트레이너의 팁은 센터에서 제공한 안내입니다.</p>`:`<p>${m.sourceLabel}</p><p>패드 위치와 사용 방식은 센터에서 확인한 설명을 반영했습니다. 동작 그림은 이를 단순화한 안내입니다.</p>`}</details>`;}
function showMachine(machine,modeIndex=0){
 const m=machine.modes?machine.modes[modeIndex]:machine;
 open(`<p class="eyebrow" style="margin-top:24px">${machine.category} / ${machine.en}</p><h2 id="detail-title">${machine.name}</h2><p class="detail-sub">${machine.brand}</p><figure class="machine-photo"><img src="assets/${machine.image}" alt="${machine.name} 머신" width="${machine.imageWidth||1086}" height="${machine.imageHeight||1448}" decoding="async"><figcaption>1986 원흥점${machine.modes?' · 하나의 머신, 두 가지 운동':''}</figcaption></figure>${machine.modes?`<section class="exercise-picker" aria-label="운동 선택"><p>운동을 선택하면 해당 사용법과 팁이 표시됩니다.</p><div class="exercise-mode-buttons">${machine.modes.map((mode,i)=>`<button type="button" data-mode="${i}" aria-pressed="${i===modeIndex}" aria-controls="exercise-panel">${mode.name}<small>${mode.category}</small></button>`).join('')}</div></section>`:''}<section id="exercise-panel" aria-label="${m.name} 안내">${machine.modes?`<h3 class="mode-title">${m.name}</h3>`:''}${exerciseContent(m)}</section>`);
 dialog.scrollTop=0;disposeMotion=initMotion();
 document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{
  const next=Number(button.dataset.mode);if(next===modeIndex)return;
  const scrollTop=dialog.scrollTop;disposeMotion();modeIndex=next;
  const mode=machine.modes[next],panel=document.querySelector('#exercise-panel');
  panel.setAttribute('aria-label',`${mode.name} 안내`);
  panel.innerHTML=`<h3 class="mode-title">${mode.name}</h3>${exerciseContent(mode)}`;
  document.querySelectorAll('[data-mode]').forEach(item=>item.setAttribute('aria-pressed',String(Number(item.dataset.mode)===next)));
  disposeMotion=initMotion();dialog.scrollTop=scrollTop;
  button.focus({preventScroll:true});
 });
}
search.addEventListener('input',render);
document.querySelector('#reset').onclick=()=>{search.value='';filters.querySelector('button').click();search.focus();};
document.querySelector('#close').onclick=()=>dialog.close();
dialog.addEventListener('close',()=>{disposeMotion();disposeMotion=()=>{};document.body.style.overflow='';});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
document.querySelector('#help').onclick=()=>open('<h2 id="detail-title">머신 가이드 이용 안내</h2><p class="detail-sub">머신과 블랙보드에 부착한 같은 QR로 이 페이지에 접속합니다.</p><section class="detail-section"><h3>01 · 이름 또는 운동 부위로 찾기</h3><p>머신에 적힌 이름을 검색하거나 부위 버튼을 눌러보세요. 띄어쓰기를 하지 않아도 검색됩니다.</p></section><section class="detail-section"><h3>02 · 머신 선택 후 안내 확인</h3><p>세팅, 사용법, 티칭 포인트 순서로 확인할 수 있도록 구성했습니다.</p></section><section class="detail-section"><h3>03 · 도움이 필요할 때</h3><p>머신을 찾기 어렵거나 조절 방법이 궁금하면 현장 직원에게 문의해주세요.</p></section><p class="draft">처음 이용하는 머신의 무게와 조절 방법은 현장 직원에게 확인해주세요.</p>');
render();

const routineNames={full:'전신 루틴',upper:'상체 루틴',lower:'하체 루틴'};
function showBeginner(){
 open(`<p class="eyebrow" style="margin-top:24px">1986 WONHEUNG / BEGINNER</p><h2 id="detail-title">초보자 운동 가이드</h2><p class="detail-sub">원하는 루틴을 선택해주세요.</p><div class="beginner-options">${Object.entries(routineNames).map(([key,name],i)=>`<button class="routine-slot" data-routine="${key}"><span class="routine-index">0${i+1} / BEGINNER</span><strong>${name}</strong><span class="routine-bottom">루틴 준비 중 <b aria-hidden="true">↗</b></span></button>`).join('')}</div>`);
 dialog.scrollTop=0;
 document.querySelectorAll('[data-routine]').forEach(button=>button.onclick=()=>{open(`<button class="routine-back" id="back-beginner">← 초보자 루틴 선택</button><p class="eyebrow" style="margin-top:24px">1986 WONHEUNG / BEGINNER</p><h2 id="detail-title">초보자 ${routineNames[button.dataset.routine]}</h2><div class="routine-rule"><p><strong>루틴을 준비하고 있어요.</strong></p><p>원흥점 머신 등록이 끝나면 운동 순서와 사용법을 안내해드릴게요.</p></div>`);dialog.scrollTop=0;document.querySelector('#back-beginner').onclick=()=>{showBeginner();document.querySelector('#detail-title').setAttribute('tabindex','-1');document.querySelector('#detail-title').focus();};document.querySelector('#back-beginner').focus();});
}
document.querySelector('#beginner-level').onclick=showBeginner;
document.querySelectorAll('[data-level]').forEach(button=>button.onclick=()=>{open(`<p class="eyebrow" style="margin-top:24px">1986 WONHEUNG / TRAINING GUIDE</p><h2 id="detail-title">${button.dataset.level} 운동 가이드</h2><div class="routine-rule"><p><strong>준비 중입니다.</strong></p><p>머신 등록 후 단계에 맞는 루틴을 안내해드릴게요.</p></div>`);dialog.scrollTop=0;});

const mascot = document.querySelector('.hero-mascot');
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
let mascotPaused = false;
function syncMascot() {
  if (!mascot) return;
  mascot.disabled = reducedMotion.matches;
  mascot.setAttribute('aria-pressed', String(mascotPaused || reducedMotion.matches));
  const label = reducedMotion.matches ? '움직임 줄이기 설정으로 정지된 마스코트' : mascotPaused ? '마스코트 덤벨 운동 재생' : '마스코트 덤벨 운동 일시정지';
  mascot.setAttribute('aria-label', label);
  mascot.title = label;
}
mascot?.addEventListener('click', () => {
  if (reducedMotion.matches) return;
  mascotPaused = !mascotPaused;
  syncMascot();
});
reducedMotion.addEventListener('change', syncMascot);
syncMascot();
